const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const scale = 3000;
  const countyFC = ee.FeatureCollection('TIGER/2018/Counties')
    .filter(ee.Filter.eq('STATEFP', '36')) // New York
    .filter(ee.Filter.eq('NAME', 'Nassau'));
  const county = countyFC.first();
  const geom = ee.Feature(county).geometry();

  const years = [2018, 2019, 2021];
  const dateRange = (y) => [ee.Date.fromYMD(y, 10, 1), ee.Date.fromYMD(y, 10, 24)]; // end exclusive, includes 23rd

  // Helper to get info
  function getInfoAsync(obj) {
    return new Promise((resolve, reject) => {
      obj.getInfo((res, err) => (err ? reject(err) : resolve(res)));
    });
  }

  async function computeYearMetrics(year) {
    const [start, end] = dateRange(year);
    // Primary: OFFL
    let col = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(start, end)
      .filterBounds(geom);
    let countPrimary = await getInfoAsync(col.size());
    let datasetUsed = 'OFFL';
    if (countPrimary === 0) {
      // Fallback: NRTI
      col = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_NO2')
        .filterDate(start, end)
        .filterBounds(geom);
      const countFallback = await getInfoAsync(col.size());
      datasetUsed = 'NRTI';
      if (countFallback === 0) {
        return { year, datasetUsed, images: 0, c1: true };
      }
    }
    // Mask by QA >= 0.75
    const colMasked = col.map(function(img) {
      const qaMask = img.select('qa_value').gte(0.75);
      const tro = img.select('tropospheric_NO2_column_number_density').updateMask(qaMask);
      const cf = img.select('cloud_fraction'); // keep for cloud stats
      return tro.addBands(cf);
    });

    // Temporal means
    const troMeanImg = colMasked.select('tropospheric_NO2_column_number_density').mean();
    const cloudMeanImg = col.select('cloud_fraction').mean(); // unmasked cloud mean over period

    // Pixel counts
    const validPixelCount = ee.Number(
      troMeanImg.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9
      }).get('tropospheric_NO2_column_number_density')
    );

    const totalPixelCount = ee.Number(
      ee.Image(1).rename('ones').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9
      }).get('ones')
    );

    const no2Mean = ee.Number(
      troMeanImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9
      }).get('tropospheric_NO2_column_number_density')
    );

    const cloudMean = ee.Number(
      cloudMeanImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9
      }).get('cloud_fraction')
    );

    // Bring to client
    const [imgCount, vCount, tCount, no2Val, cloudVal] = await Promise.all([
      getInfoAsync(col.size()),
      getInfoAsync(validPixelCount),
      getInfoAsync(totalPixelCount),
      getInfoAsync(no2Mean),
      getInfoAsync(cloudMean)
    ]);

    // Checks
    if (imgCount === 0) return { year, datasetUsed, images: 0, c1: true };
    if (!vCount || vCount === 0) return { year, datasetUsed, images: imgCount, valid: 0, total: tCount, cloud: cloudVal, c2: true };
    if (no2Val === null || Number.isNaN(no2Val)) return { year, datasetUsed, images: imgCount, valid: vCount, total: tCount, cloud: cloudVal, c3: true };

    return {
      year,
      datasetUsed,
      images: imgCount,
      valid: vCount,
      total: tCount,
      cloud: cloudVal,
      no2: no2Val
    };
  }

  try {
    const metricsList = [];
    for (const y of years) {
      const m = await computeYearMetrics(y);
      metricsList.push(m);
    }

    // Print concise evidence
    for (const m of metricsList) {
      if (m.c1) {
        console.log(`${m.year} ${m.datasetUsed} Images: 0`);
      } else if (m.c2) {
        const vp = m.total ? (100 * 0 / m.total).toFixed(1) : '0.0';
        const cloudPct = m.cloud != null ? (100 * m.cloud).toFixed(1) : 'NA';
        console.log(`${m.year} ${m.datasetUsed} Images: ${m.images}, Valid px: 0/${m.total} (0.0%), Cloud: ${cloudPct}%`);
      } else if (m.c3) {
        const cloudPct = m.cloud != null ? (100 * m.cloud).toFixed(1) : 'NA';
        const vp = m.total ? (100 * (m.valid || 0) / m.total).toFixed(1) : '0.0';
        console.log(`${m.year} ${m.datasetUsed} Images: ${m.images}, Valid px: ${m.valid}/${m.total} (${vp}%), Cloud: ${cloudPct}%, NO2: NaN`);
      } else {
        const vp = m.total ? (100 * m.valid / m.total).toFixed(1) : '0.0';
        const cloudPct = (100 * m.cloud).toFixed(1);
        // NO2 in mol/m^2; print in 1e-5 mol/m^2 for readability
        const no2e5 = (m.no2 * 1e5).toFixed(2);
        console.log(`${m.year} ${m.datasetUsed} Images: ${m.images}, Valid px: ${m.valid}/${m.total} (${vp}%), Cloud: ${cloudPct}%, NO2(x1e-5 mol/m^2): ${no2e5}`);
      }
    }

    // Decision logic and final tag
    // Failures handling
    if (metricsList.some(m => m.c1)) {
      console.log('C1: Empty Collection (No images found in date/location for one or more years).');
      console.log('C1');
      return;
    }
    if (metricsList.some(m => m.c2)) {
      console.log('C2: No Valid Pixels after QA/masking for one or more years.');
      console.log('C2');
      return;
    }
    if (metricsList.some(m => m.c3)) {
      console.log('C3: Calculation Failure (null/NaN).');
      console.log('C3');
      return;
    }

    const byYear = {};
    metricsList.forEach(m => { byYear[m.year] = m; });

    const v2018 = byYear[2018]?.no2;
    const v2019 = byYear[2019]?.no2;
    const v2021 = byYear[2021]?.no2;

    if ([v2018, v2019, v2021].some(v => v === null || v === undefined || Number.isNaN(v))) {
      console.log('C3: Calculation Failure (missing values).');
      console.log('C3');
      return;
    }

    const isLower = (v2021 < v2019) && (v2021 < v2018);
    console.log(isLower ? 'A: Yes' : 'B: No');
    console.log(isLower ? 'A: Yes' : 'B: No'); // Final line must be the tag
  } catch (err) {
    console.log(`D: ${err && err.message ? err.message : 'Processing error'}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
